"""Small reproducible mathematical checks for all-species BM/OU/WN analysis."""
from __future__ import annotations

import numpy as np
import pytest

from analysis.v4.t2_full_species_bm_ou import (
    fit_three_models, PRIMARY_S1_N, PLACEMENT_N, NUCLEAR_N, FIXED_S1,
)


def test_bm_is_nested_inside_ou_and_winner_is_one_of_three():
    rng=np.random.default_rng(4)
    n=14
    # A proper Brownian shared-root matrix generated by inherited root-to-tip
    # shared branch and individual positive terminal edges.
    C=np.ones((n,n))*0.3+np.eye(n)*0.8
    y=np.linspace(-1.1,1.1,n)+rng.normal(0,.15,n)
    X=np.column_stack([np.ones(n), np.linspace(-1,1,n)])
    out=fit_three_models(y,X,np.diag(C),C,grid_points=15)
    assert out["n_tips"]==n
    assert set(out["aicc"])=={"WN","BM","OU1"}
    assert out["preferred"] in {"WN","BM","OU1"}
    assert out["loglik"]["OU1"]+1e-8 >= out["loglik"]["BM"]
    assert np.isfinite(list(out["aicc"].values())).all()


def test_invalid_species_label_and_unknown_covariance_are_blocked():
    n=10
    C=np.ones((n,n))*.3+np.eye(n)*.7
    y=np.linspace(1,3,n)
    X=np.column_stack([np.ones(n),np.arange(n)])
    with pytest.raises(ValueError, match="Unidentified"):
        fit_three_models(np.ones(n),X,np.diag(C),C)
    with pytest.raises(ValueError, match="Unidentified"):
        fit_three_models(y,X,np.diag(C),C[:9,:9])


def test_full_census_and_climate_axes_not_small_filtered_pilot():
    assert PRIMARY_S1_N==191
    assert PLACEMENT_N==52
    assert NUCLEAR_N==63
    assert FIXED_S1==("chelsa_bio01","chelsa_bio04","chelsa_bio12",
                      "chelsa_bio15","chelsa_rsds_mean")


def test_climate_regression_rank_guard():
    n=14
    C=np.ones((n,n))*.2+np.eye(n)
    y=np.linspace(1,4,n)
    X=np.ones((n,2))
    with pytest.raises(ValueError,match="Unidentified"):
        fit_three_models(y,X,np.diag(C),C)
